"""Compact same-origin Minecraft operations console."""

PAGE = r'''<!doctype html>
<html lang="vi">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="dark"><title>MC Console</title>
<style>
:root{font-family:Inter,ui-sans-serif,system-ui,sans-serif;color:#e9edf5;background:#0a0d13;font-synthesis:none}*{box-sizing:border-box}body{margin:0;min-width:280px;background:radial-gradient(ellipse at 15% 0%,#162539 0,transparent 52%),#0a0d13}main{max-width:1080px;margin:auto;padding:24px 18px}.top{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:18px}.brand{display:flex;align-items:center;gap:10px;font-weight:750;letter-spacing:-.5px;font-size:18px}.mark{display:grid;place-items:center;width:31px;height:31px;background:#9fee86;color:#132a15;border-radius:9px;font-size:15px}.connection{font-size:11px;color:#9ba8ba;display:flex;align-items:center;gap:6px}.dot{width:6px;height:6px;border-radius:50%;background:#748093}.connection[data-online=true] .dot{background:#9fee86;box-shadow:0 0 10px #9fee8650}.panel{border:1px solid #27313f;background:#111722;border-radius:15px;overflow:hidden;box-shadow:0 14px 50px #0002}.controls{display:grid;grid-template-columns:1fr 1fr;gap:12px}.card{padding:18px}.label{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:17px;font-size:13px;font-weight:650}.badge{font-size:10px;font-weight:500;letter-spacing:.2px;border:1px solid #334052;border-radius:20px;color:#a6b3c5;padding:4px 8px;white-space:nowrap}.badge.good{color:#adf49a;background:#9fee860b;border-color:#9fee8635}.actions{display:flex;gap:7px}button{font:inherit;font-size:12px;font-weight:650;cursor:pointer;border:1px solid #344052;color:#d9e1ed;background:#1b2432;border-radius:8px;min-height:37px;padding:8px 14px;transition:background .15s,opacity .15s}button:hover{background:#293548}button.primary{background:#a6ee8e;border-color:#a6ee8e;color:#182b13}button.primary:hover{background:#bcffa7}button.stop{color:#f2a8ac;background:#f2778109;border-color:#a25a6340}button:disabled{opacity:.35;cursor:not-allowed}button:focus-visible,input:focus-visible{outline:2px solid #a6ee8e;outline-offset:3px}.automation{display:flex;align-items:center;justify-content:space-between;padding:13px 18px;margin-top:12px;font-size:12px}.switch{position:relative;display:inline-flex;align-items:center;gap:10px;cursor:pointer;color:#aab7c7}.switch input{position:absolute;right:0;opacity:0;width:38px;height:23px;margin:0}.track{display:block;width:36px;height:21px;border-radius:20px;background:#334052;transition:background .2s;pointer-events:none}.track:after{content:'';display:block;width:15px;height:15px;margin:3px;border-radius:50%;background:#c5cdd8;transition:transform .2s}.switch input:checked+.track{background:#a6ee8e}.switch input:checked+.track:after{transform:translateX(15px);background:#172711}.switch input:focus-visible+.track{outline:2px solid #a6ee8e;outline-offset:3px}.switch input:disabled+.track{opacity:.4}.console{margin-top:16px}.bar{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px;padding:12px 16px;border-bottom:1px solid #253040}.caption{font-size:12px;font-weight:650;display:flex;align-items:center;gap:8px}.live{font-size:9px;letter-spacing:1px;color:#a6ee8e}.meta{display:flex;gap:6px;flex-wrap:wrap}.meta .badge{font-size:10px}pre{margin:0;padding:16px;height:clamp(240px,43vh,480px);overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font:11px/1.8 ui-monospace,SFMono-Regular,Consolas,monospace;color:#b9c8dc;background:#0c111a;scrollbar-color:#344052 transparent}.command{display:flex;align-items:center;gap:9px;padding:10px 12px;border-top:1px solid #253040}.prompt{font-family:monospace;color:#a6ee8e;font-size:16px}.command input{min-width:0;flex:1;background:transparent;border:0;padding:8px 4px;color:#e9edf5;font:16px ui-monospace,monospace;outline-offset:0}.command input::placeholder{color:#66758b}.command button{min-height:33px;padding:6px 12px}.footer{display:flex;justify-content:space-between;gap:12px;font-size:10px;color:#77869c;margin-top:11px}.message{min-height:18px;font-size:12px;margin-top:10px;color:#a6ee8e;overflow-wrap:anywhere}.message.error{color:#ffadb2}#run{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:55%}@media(max-width:560px){main{padding:16px 12px}.controls{grid-template-columns:1fr;gap:9px}.card{padding:14px}.label{margin-bottom:12px}.actions button{flex:1;padding:8px}.top{margin-bottom:14px}.bar{padding:11px 12px}.meta{gap:4px}.footer{font-size:9px}pre{height:36vh;min-height:220px;padding:12px}.automation{margin-top:9px}}
</style></head>
<body><main>
<header class="top"><div class="brand"><span class="mark" aria-hidden="true">▦</span> MC Console</div><div id="connection" class="connection"><span class="dot"></span><span id="connectionText">Đang kết nối</span></div></header>
<div class="panel automation" style="margin-bottom:12px"><span>IP server</span><button type="button" id="copyIP">160.191.51.148:25577 · Sao chép</button></div><div class="controls">
<section class="panel card" aria-label="Job server"><div class="label">Job server <span id="jobStatus" class="badge">—</span></div><div class="actions" role="group" aria-label="Điều khiển job server"><button class="primary" data-action="start">Start</button><button data-action="restart">Restart</button><button class="stop" data-action="stop">Stop</button></div></section>
<section class="panel card" aria-label="Minecraft"><div class="label">Minecraft <span id="mcStatus" class="badge">—</span></div><div class="actions" role="group" aria-label="Điều khiển Minecraft"><button class="primary" data-action="mc_start" disabled>Start</button><button data-action="mc_restart" disabled>Restart</button><button class="stop" data-action="mc_stop">Stop</button></div></section>
</div>
<div class="panel automation"><span>Chạy liên tục</span><label class="switch"><span>24/7</span><input id="continuous" type="checkbox" role="switch" aria-label="Chạy liên tục 24/7" disabled><span class="track"></span></label></div>
<section class="panel console" aria-label="Console trực tiếp"><div class="bar"><div class="caption">Console <span class="live">LIVE</span></div><div class="meta"><span id="sync" class="badge">Sync —</span><span id="snapshot" class="badge">Snapshot —</span></div></div><pre id="log" tabindex="0" aria-label="Log server">Đang tải log…</pre><form id="commandForm" class="command"><span class="prompt" aria-hidden="true">›</span><input id="command" name="command" placeholder="Nhập lệnh Minecraft…" autocomplete="off" aria-label="Lệnh Minecraft" required><button type="submit">Gửi ↵</button></form></section>
<div class="footer"><span id="run">Run —</span><span id="updated">Cập nhật mỗi 2 giây</span></div><div id="message" class="message" role="status" aria-live="polite"></div>
</main><script>
'use strict';
const $=id=>document.getElementById(id);
let state=null, busy=false, polling=false, generation=0, timer=null;const requests=new Set();
const buttons=[...document.querySelectorAll('[data-action]')];
function message(text,error=false){$('message').textContent=text;$('message').classList.toggle('error',error)}
async function api(path,body){
 const controller=new AbortController();requests.add(controller);const timeout=setTimeout(()=>controller.abort(),body===undefined?12000:50000);
 const options={credentials:'include',cache:'no-store',headers:{Accept:'application/json'},signal:controller.signal};
 try{
 if(body!==undefined){options.method='POST';options.headers['Content-Type']='application/json';options.body=JSON.stringify(body)}
 const response=await fetch(path,options);let result;
 try{result=await response.json()}catch{throw new Error('Phản hồi không hợp lệ (HTTP '+response.status+')')}
 if(!response.ok||result.ok===false)throw new Error(result.message||result.error||'HTTP '+response.status);
 return result;
 }finally{clearTimeout(timeout);requests.delete(controller)}
}
function activeJob(s){return Boolean(s&&(s.run_id||(Array.isArray(s.control?.active)&&s.control.active.length)||['running','starting','queued','in_progress'].includes(s.phase)))}
function updateControls(){const active=activeJob(state);for(const button of buttons){button.disabled=busy||(button.dataset.action==='mc_start'||button.dataset.action==='mc_restart')&&!active}$('continuous').disabled=busy||!state;$('command').disabled=busy;$('commandForm').querySelector('button').disabled=busy}
function badge(id,text,good=false){$(id).textContent=text;$(id).classList.toggle('good',good)}
function render(s){state=s;const active=activeJob(s);badge('jobStatus',active?'Đang chạy':'Đã dừng',active);badge('mcStatus',s.minecraft_running?'Đang chạy':'Đã dừng',!!s.minecraft_running);$('continuous').checked=!!s.control?.enabled;
 const sync=s.sync||{}, conflicts=Array.isArray(sync.conflicts)?sync.conflicts.length:Number(sync.conflicts||0),pending=Number(sync.pending||0);badge('sync',conflicts?'Sync · '+conflicts+' xung đột':pending?'Sync · '+pending+' chờ':'Sync · '+({syncing:'Đang đồng bộ',applying:'Đang áp dụng',error:'Lỗi'}[sync.state]||'Sẵn sàng'),!conflicts&&!pending);$('sync').title=s.published?.commit?String(s.published.commit):'';
 const snapshot=s.last_snapshot;badge('snapshot',sync.last_sync?'Lưu '+new Date(sync.last_sync*1000).toLocaleTimeString('vi-VN'):'Chưa đồng bộ');$('run').textContent='Run '+(s.run_id||'—');$('run').title=s.run_id||'';
 const log=$('log'),atBottom=log.scrollHeight-log.scrollTop-log.clientHeight<45;const text=Array.isArray(s.log)?s.log.map(line=>typeof line==='string'?line:JSON.stringify(line)).join('\n'):String(s.log||'Chưa có log.');if(log.textContent!==text){log.textContent=text;if(atBottom)log.scrollTop=log.scrollHeight}
 $('updated').textContent='Cập nhật '+new Date().toLocaleTimeString('vi-VN');updateControls();
}
async function poll(){if(polling||document.hidden)return;const stamp=generation;polling=true;try{const result=await api('/api/status?fresh='+Date.now());if(stamp!==generation)return;render(result);$('connection').dataset.online='true';$('connectionText').textContent='Đã kết nối'}catch(error){if(stamp!==generation)return;$('connection').dataset.online='false';$('connectionText').textContent='Mất kết nối';message(error.message,true)}finally{if(stamp===generation)polling=false}}
async function control(action){if(busy)return;busy=true;updateControls();message('Đang xử lý…');try{const result=await api('/api/control',{action});message(result.message||'Đã gửi yêu cầu.');await poll()}catch(error){message(error.message,true)}finally{busy=false;updateControls();if(state)$('continuous').checked=!!state.control?.enabled}}
buttons.forEach(button=>button.addEventListener('click',()=>control(button.dataset.action)));
$('continuous').addEventListener('change',event=>control(event.target.checked?'enable':'disable'));
$('commandForm').addEventListener('submit',async event=>{event.preventDefault();const input=$('command'),command=input.value.trim();if(!command||busy)return;busy=true;updateControls();try{const result=await api('/api/command',{command});input.value='';message(result.message||'Đã gửi lệnh.');await poll()}catch(error){message(error.message,true)}finally{busy=false;updateControls();if(!document.hidden)input.focus()}});
async function loop(){const stamp=generation;await poll();if(stamp===generation&&!document.hidden)timer=setTimeout(loop,2000)}
function reconnect(){generation++;clearTimeout(timer);for(const request of requests)request.abort();requests.clear();polling=false;busy=false;updateControls();if(!document.hidden){$('connectionText').textContent='Đang kết nối lại';loop()}}
window.addEventListener('online',reconnect);window.addEventListener('pageshow',reconnect);document.addEventListener('visibilitychange',reconnect);window.addEventListener('pagehide',()=>{generation++;clearTimeout(timer);for(const request of requests)request.abort();polling=false;busy=false});
$('copyIP').onclick=async()=>{try{await navigator.clipboard.writeText('160.191.51.148:25577');message('Đã sao chép IP')}catch{message('IP: 160.191.51.148:25577')}};
loop();
</script></body></html>'''
